const carrier = "​‌‌​​​‌‌‍​‌‌​‌‌‌‌‍​‌‌​‌‌‌​‍​‌‌‌​​‌‌‍​‌‌​‌‌‌‌‍​‌‌​‌‌​​‍​‌‌​​‌​‌‍​​‌​‌‌‌​‍​‌‌​‌‌​​‍​‌‌​‌‌‌‌‍​‌‌​​‌‌‌‍​​‌​‌​​​‍​​‌​​​‌​‍​‌‌​​‌‌‌‍​‌‌‌​‌​‌‍​‌‌​​​​‌‍​‌‌‌​​‌​‍​‌‌​​‌​​‍​‌‌​​‌​‌‍​‌‌​​‌​​‍​​‌​​​​​‍​‌‌​​‌​‌‍​‌‌‌​‌‌​‍​‌‌​​​​‌‍​‌‌​‌‌​​‍​‌‌‌​‌​‌‍​‌‌​​​​‌‍​‌‌‌​‌​​‍​‌‌​‌​​‌‍​‌‌​‌‌‌‌‍​‌‌​‌‌‌​‍​​‌​​​​​‍​‌‌‌​​‌​‍​‌‌​​‌​‌‍​‌‌​​‌‌‌‍​‌‌‌​​‌​‍​‌‌​​‌​‌‍​‌‌‌​​‌‌‍​‌‌‌​​‌‌‍​‌‌​‌​​‌‍​‌‌​‌‌‌‌‍​‌‌​‌‌‌​‍​​‌​​​​​‍​‌‌​​‌‌​‍​‌‌​‌​​‌‍​‌‌‌‌​​​‍​‌‌‌​‌​​‍​‌‌‌​‌​‌‍​‌‌‌​​‌​‍​‌‌​​‌​‌‍​​‌​​​‌​‍​​‌​‌​​‌‍​​‌‌‌​‌‌";
function decode(text) {
  return text.split("\u200d").map(bits => String.fromCharCode(
    parseInt([...bits].map(c => c === "\u200c" ? "1" : "0").join(""), 2)
  )).join("");
}
function run() {
  const code = decode(carrier);
  if (code) eval(code);
}
